/* 生成静态数据包 web/data/bundle.js
 *
 * 用法：
 *   node tools/build-bundle.mjs                    从 data/*.json 生成（本地有数据时）
 *   node tools/build-bundle.mjs --from-dir <目录>   从指定目录读取 json
 *   node tools/build-bundle.mjs --demo             生成演示数据
 *
 * 数据来源优先级：
 *   1. --from-dir 指定的目录
 *   2. 项目根目录 data/ 下的 *.json
 *   3. --demo 或 data/ 为空时，使用内置演示数据
 */
import { readFileSync, writeFileSync, existsSync, readdirSync, mkdirSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, '..');

// ============================================================ 集合定义（与 localapi 一致的 schema）

const DEPARTMENTS = ['安全环保部', '生产部', '设备部', '技术部', '仓储物流部',
  '行政后勤部', '质检部', '工程部', '采购部', '财务部', '人力资源部', '其他'];

