const PREFIXES = {
  hazards: 'YH', risks: 'FX', concerns: 'AQ', incidents: 'SG',
  trainings: 'PX', certificates: 'ZZ', fireEquipments: 'XF',
  fireDrills: 'YL', contractors: 'CBS', permits: 'ZY', equipments: 'SB',
};

// ============================================================ 读取 schema

function loadSchema() {
  // schema 从 web/localapi.js 里没有独立文件，这里内置一份精简版
  // 实际字段定义来自原 Python schema.py 的导出结果
  const schemaPath = join(ROOT, 'tools', 'schema.json');
  if (existsSync(schemaPath)) {
    return JSON.parse(readFileSync(schemaPath, 'utf8'));
  }
  throw new Error('缺少 tools/schema.json，请先运行 node tools/export-schema.mjs');
}

// ============================================================ 主流程

function today() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function nowStr() {
  const d = new Date();
  return `${today()} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}:${String(d.getSeconds()).padStart(2, '0')}`;
}

function main() {
  const args = process.argv.slice(2);
  let fromDir = '';
  let useDemo = false;

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--from-dir' && args[i + 1]) { fromDir = args[++i]; }
    else if (args[i] === '--demo') { useDemo = true; }
  }

  console.log('='.repeat(66));
  console.log('生成静态数据包');
  console.log('='.repeat(66));

  const schema = loadSchema();
  const data = {};

  const srcDir = fromDir ? resolve(fromDir) : join(ROOT, 'data');
  let loaded = 0;

  if (!useDemo && existsSync(srcDir)) {
    for (const coll of schema.collections) {
      const path = join(srcDir, `${coll.key}.json`);
      if (existsSync(path)) {
        try {
          const raw = JSON.parse(readFileSync(path, 'utf8'));
          data[coll.key] = raw.items || [];
          loaded += data[coll.key].length;
        } catch (e) {
          console.warn(`  警告：${coll.key}.json 解析失败，跳过`);
          data[coll.key] = [];
        }
      } else {
        data[coll.key] = [];
      }
    }
  } else {
    schema.collections.forEach(c => { data[c.key] = []; });
  }

  if (useDemo || loaded === 0) {
    console.log('\n使用内置演示数据…');
    const demo = buildDemoData(schema);
    schema.collections.forEach(c => {
      data[c.key] = demo[c.key] || [];
    });
    loaded = Object.values(data).reduce((s, a) => s + a.length, 0);
  }

  const total = Object.values(data).reduce((s, a) => s + a.length, 0);
  const meta = {
    generatedAt: nowStr(),
    total,
    version: '2.0.0-static',
    counts: Object.fromEntries(Object.entries(data).map(([k, v]) => [k, v.length])),
  };

  const bundle = { schema, data, meta };
  const payload = JSON.stringify(bundle);
  const content = `/* 安全管理数据工作台 — 静态数据包
 * 生成时间：${meta.generatedAt}
 * 记录总数：${total}
 * 本文件由 tools/build-bundle.mjs 自动生成，请勿手动修改
 */
window.__EHS_BUNDLE__ = ${payload};
`;

  const outDir = join(ROOT, 'web', 'data');
  mkdirSync(outDir, { recursive: true });
  const outFile = join(outDir, 'bundle.js');
  writeFileSync(outFile, content, 'utf8');

  const sizeKb = Math.round(Buffer.byteLength(content) / 1024);
  console.log('');
  console.log(`已生成：web/data/bundle.js`);
  console.log(`文件大小：${sizeKb} KB　｜　记录总数：${total}`);
  console.log('');
  console.log('下一步：git add web/data/bundle.js && git commit && git push');
  return 0;
}

